namespace Alis.Reactive
{
    /// <summary>
    /// Immutable registration of a component in the reactive plan.
    /// Populated at view render time by each vertical slice's HtmlExtensions.
    /// Consumed by GatherResolver (HTTP serialization) and ValidationResolver (field enrichment).
    /// </summary>
    public sealed class ComponentRegistration
    {
        /// <summary>DOM element ID generated by IdGenerator from the model expression.</summary>
        public string ComponentId { get; }

        /// <summary>"native" or "fusion" — determines resolveRoot() strategy at runtime.</summary>
        public string Vendor { get; }

        /// <summary>Model property path (e.g., "AdmissionDate", "Address.Street") — key in ComponentsMap.</summary>
        public string BindingPath { get; }

        /// <summary>Dot-path from vendor root to the readable value (e.g., "value", "checked").</summary>
        public string ReadExpr { get; }

        /// <summary>Semantic component kind (e.g., "datepicker", "numerictextbox") — descriptive, not used for coercion.</summary>
        public string ComponentType { get; }

        /// <summary>
        /// Coercion type inferred from typeof(TProp) via CoercionTypes.InferFromType at registration.
        /// Flows to plan JSON → consumed by gather (daterange decomposition) and validation (field enrichment).
        /// Values: "string", "number", "boolean", "date", "array", "raw".
        /// </summary>
        public string CoerceAs { get; }

        /// <summary>
        /// NEVER make public. Constructed exclusively by framework builders. Public constructors
        /// on descriptor types allow devs to bypass the builder API and create invalid plan state.
        /// </summary>
        internal ComponentRegistration(string componentId, string vendor, string bindingPath, string readExpr, string componentType, string coerceAs)
        {
            ComponentId = componentId;
            Vendor = vendor;
            BindingPath = bindingPath;
            ReadExpr = readExpr;
            ComponentType = componentType;
            CoerceAs = coerceAs;
        }

        /// <summary>
        /// Returns whether <paramref name="other"/> registers the identical component.
        /// </summary>
        /// <remarks>
        /// Compares <see cref="ComponentId"/>, <see cref="Vendor"/>, <see cref="ReadExpr"/>,
        /// <see cref="ComponentType"/>, and <see cref="CoerceAs"/>. <see cref="BindingPath"/> is
        /// excluded because callers compare registrations already keyed by the same binding
        /// path, so it is equal by construction.
        /// </remarks>
        internal bool IsSameRegistrationAs(ComponentRegistration other)
        {
            return ComponentId == other.ComponentId
                && Vendor == other.Vendor
                && ReadExpr == other.ReadExpr
                && ComponentType == other.ComponentType
                && CoerceAs == other.CoerceAs;
        }

        /// <summary>
        /// Returns the registration's identifying fields as a bracketed list for
        /// diagnostics, e.g. <c>[name-input, native, value, textbox, string]</c>.
        /// </summary>
        /// <returns>The component id, vendor, read expression, component type, and coercion.</returns>
        public override string ToString()
        {
            return $"[{ComponentId}, {Vendor}, {ReadExpr}, {ComponentType}, {CoerceAs}]";
        }

        /// <summary>
        /// Projects the registration to the shape embedded in the plan JSON:
        /// <c>{ id, vendor, readExpr, componentType, coerceAs }</c>.
        /// </summary>
        /// <remarks>
        /// <see cref="BindingPath"/> is omitted because it is the key under which the
        /// registration is stored in the plan's components map.
        /// </remarks>
        /// <returns>An object carrying the registration's serialized fields.</returns>
        internal object ToSerializableShape()
        {
            return new
            {
                id = ComponentId,
                vendor = Vendor,
                readExpr = ReadExpr,
                componentType = ComponentType,
                coerceAs = CoerceAs
            };
        }
    }
}
